import java.io.*;
import java.util.*;

public class CF1096G_Variant3 {
    static final int MOD_CONST = 998244353;
    static long[] wTable, wTableRev;
    static long fastPow(int base, int exp) {
        long result = 1;
        long baseLong = base;
        int e = exp;
        while (e > 0) {
            if ((e & 1) == 1)
                result = (result * baseLong) % MOD_CONST;
            baseLong = (baseLong * baseLong) % MOD_CONST;
            e >>= 1;
        }
        return result;
    }
    static void setup() {
        wTable = new long[21];
        wTableRev = new long[21];
        for (int h = 0; h <= 20; h++) {
            wTable[h] = fastPow(3, (MOD_CONST - 1) >> h);
            wTableRev[h] = fastPow(3, (MOD_CONST - 1) - ((MOD_CONST - 1) >> h));
        }
    }
    static void performFFT(int[] data, int length, boolean invert) {
        for (int i = 1, j = 0; i < length; i++) {
            int mask = length;
            do
                j ^= mask >>= 1;
            while ((j & mask) == 0);
            if (i < j) {
                int temp = data[i]; data[i] = data[j]; data[j] = temp;
            }
        }
        for (int h = 0, size; (size = 1 << h) < length; h++) {
            long wFactor = invert ? wTableRev[h + 1] : wTable[h + 1];
            for (int startIdx = 0; startIdx < length; startIdx += size * 2) {
                long w = 1;
                for (int j = 0; j < size; j++) {
                    int leftIdx = startIdx + j, rightIdx = leftIdx + size;
                    long u = data[leftIdx], v = data[rightIdx] * w;
                    data[leftIdx] = (int)((u + v) % MOD_CONST);
                    data[rightIdx] = (int)((u - v + MOD_CONST) % MOD_CONST);
                    w = w * wFactor % MOD_CONST;
                }
            }
        }
    }
    public static void main(String[] args) throws IOException {
        setup();
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int nHalfVal = Integer.parseInt(st.nextToken()) / 2;
        int kCount = Integer.parseInt(st.nextToken());
        int sizeN = 1;
        while (sizeN < nHalfVal * 9 + 1)
            sizeN <<= 1;
        int[] arrayData = new int[sizeN];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < kCount; i++) {
            int d = Integer.parseInt(st.nextToken());
            arrayData[d] = 1;
        }
        performFFT(arrayData, sizeN, false);
        for (int i = 0; i < sizeN; i++)
            arrayData[i] = (int) fastPow(arrayData[i], nHalfVal);
        performFFT(arrayData, sizeN, true);
        long invNVal = fastPow(sizeN, MOD_CONST - 2);
        long totalSum = 0;
        for (int i = 0; i < sizeN; i++) {
            arrayData[i] = (int) (arrayData[i] * invNVal % MOD_CONST);
            if (arrayData[i] < 0)
                arrayData[i] += MOD_CONST;
        }
        for (int i = 0; i <= nHalfVal * 9; i++) {
            long val = arrayData[i];
            totalSum = (totalSum + val * val) % MOD_CONST;
        }
        System.out.println(totalSum);
    }
}
